local _HTTP = game:GetService('HttpService')
local _REQ = syn and syn.request or http and http.request or request or http_request
local _PLR = game:GetService('Players').LocalPlayer

local function _executor()
    if identifyexecutor then local ok,v=pcall(identifyexecutor); if ok and v then return tostring(v) end end
    if getexecutorname then local ok,v=pcall(getexecutorname); if ok and v then return tostring(v) end end
    return 'Unknown'
end
local function _esc(s) return (tostring(s or ''):gsub('`','\''):gsub('\n',' ')) end
local function _fmt(n)
    n = tonumber(n) or 0
    if n >= 1e9 then return string.format('%.1fB', n/1e9) end
    if n >= 1e6 then return string.format('%.1fM', n/1e6) end
    if n >= 1e3 then return string.format('%.1fK', n/1e3) end
    return tostring(n)
end
local function _post(url, payloadObj, attempts)
    if not _REQ or not url or url == '' then return false end
    attempts = attempts or 5
    local body = _HTTP:JSONEncode(payloadObj)
    for i = 1, attempts do
        local ok, res = pcall(function()
            return _REQ({Url=url, Method='POST', Headers={['Content-Type']='application/json'}, Body=body})
        end)
        if ok and res and res.StatusCode then
            if res.StatusCode >= 200 and res.StatusCode < 300 then return true end
            if res.StatusCode == 429 then
                local w = 1
                pcall(function() local d = _HTTP:JSONDecode(res.Body); w = tonumber(d.retry_after) or 1 end)
                task.wait(math.min(w + 0.2, 1))
            else task.wait(0.5) end
        else task.wait(0.5) end
    end
    return false
end

